mber;\n\tcardReviews: number;\n\tquestionChecks: number;\n}\n\nexport interface LessonPlan {\n\tid: string;\n\ttopic: string;\n\tcreatedAt: number;\n\tupdatedAt: number;\n\tcontent: string;\n\tmetadata?: Record<string, unknown>;\n\tsessionId?: string;\n}\n\nexport interface LessonMap {\n\tid: string;\n\ttopic: string;\n\tcreatedAt: number;\n\tmmdContent: string;\n\tsvgContent?: string;\n\tsessionId?: string;\n}\n\nexport interface Animation {\n\tid: string;\n\ttopic: string;\n\tcreatedAt: number;\n\tstoryboard: string;\n\tscene: string;\n\tmanifest: string;\n\trenderer?: \"hyperframes\";\n\tsessionId?: string;\n}\n\nexport interface Verification {\n\tid: string;\n\ttopic: string;\n\tcreatedAt: number;\n\tchecklist: string;\n\tcompleted: boolean;\n\tsessionId?: string;\n}\n\nexport interface BenchmarkResult {\n\tid: string;\n\ttopic?: string;\n\tcreatedAt: number;\n\tscore: number;\n\ttrace?: string;\n\treport: string;\n\tsessionId?: string;\n}\n\nexport interface EvolutionResult {\n\tid: string;\n\ttopic?: string;\n\tcreatedAt: number;\n\tbestScore: number;\n\tpolicy: string;\n\ttrace?: string;\n\treport: string;\n\tsessionId?: string;\n}\n\nexport interface Policy {\n\tid: string;\n\tcreatedAt: number;\n\tupdatedAt: number;\n\tcontent: string;\n\tactive: boolean;\n}\n\nexport interface FeedbackEntry {\n\tid: string;\n\ttopic: string;\n\tsignal: \"thumbs-up\" | \"thumbs-down\" | \"confused\";\n\tcreatedAt: number;\n\tsource?: \"explicit\" | \"turn-analysis\";\n\tevidence?: string;\n\tsessionId?: string;\n\tmessageId?: string;\n\t/** The generated assistant message the learner was reacting to. */\n\treferent?: {\n\t\tsessionId: string;\n\t\tmessageId: string;\n\t\tcontent: string;\n\t\tcreatedAt?: number;\n\t};\n\t/** Makes it clear whether topic attribution is exact or merely session context. */\n\ttopicSource?: \"session-title\" | \"explicit\" | \"turn-analysis\";\n}\n\nexport interface LearnerState {\n\tschemaVersion: typeof LEARNER_STATE_SCHEMA_VERSION;\n\ttopics