artialCreditPoints === \"number\"\n\t\t? result.partialCreditPoints\n\t\t: result.score;\n\treturn totalQuestions > 0\n\t\t? Math.max(0, Math.min(1, (objectivePoints + openEndedPoints) / totalQuestions))\n\t\t: 0;\n}\n\nexport interface PromptEvolutionResult {\n\tid: string;\n\tpromptName: string;\n\tcreatedAt: number;\n\tbestScore: number;\n\tbestPrompt: string;\n\treport: string;\n\tsessionId?: string;\n}\n\nexport interface ImprovementAttemptRecord {\n\tid: string;\n\tcreatedAt: number;\n\tproposalId: string;\n\tbaselineScore: number;\n\tafterScore: number | null;\n\tscoreDelta: number | null;\n\taccepted: boolean;\n\ttargets: string;\n\thypothesis: string;\n\tsessionId?: string;\n}\n\n// ---------------------------------------------------------------------------\n// Flashcard decks & spaced-repetition state (SM-2 variant)\n// ---------------------------------------------------------------------------\n\nexport interface FlashcardSrsState {\n\tease: number;\n\tintervalDays: number;\n\treps: number;\n\tlapses: number;\n\tdueAt: number;\n\tlastReviewedAt: number;\n\tlastRating: 0 | 1 | 2 | 3 | null;\n}\n\nexport interface Flashcard {\n\tid: string;\n\tfront: string;\n\tback: string;\n\ttags?: string[];\n\tsrs: FlashcardSrsState;\n\tcreatedAt: number;\n\tupdatedAt: number;\n}\n\nexport interface FlashcardDeck {\n\tid: string;\n\ttopic: string;\n\tslug: string;\n\ttitle: string;\n\tdescription?: string;\n\tcards: Flashcard[];\n\tcreatedAt: number;\n\tupdatedAt: number;\n\tsessionId?: string;\n}\n\nexport interface CardReviewRecord {\n\tid: string;\n\tdeckId: string;\n\tcardId: string;\n\ttopic: string;\n\tslug: string;\n\trating: 0 | 1 | 2 | 3;\n\tappliedIntervalDays: number;\n\teaseAfter: number;\n\t/** The interval the learner was asked to recall over, before this review. */\n\tpreviousIntervalDays?: number;\n\tisLapse?: boolean;\n\tcreatedAt: number;\n\tsessionId?: string;\n}\n\n/** A structured comprehension checkpoint from ask_user_question. */\nexport interface QuestionCheckRecord {\n\tid: string;\n\ttopic: string;\n\tquestion: string;\n\tanswer: string;\n\t/** Undefined means the response is preserved for the tutor but has not been graded. */\n\tscore?: number;\n\tgrading: \"auto\" | \"model\" | \"pending\";\n\tmisconception?: string;\n\tcreatedAt: number;\n\tsessionId?: string;\n}\n\nexport function mergeFeedbackById(...lists: Array<FeedbackEntry[] | undefined>): FeedbackEntry[] {\n\tconst byFeedbackId = new Map<string, FeedbackEntry>();\n\tfor (const list of lists) {\n\t\tfor (const entry of list ?? []) {\n\t\t\tbyFeedbackId.set(entry.id, entry);\n\t\t}\n\t}\n\treturn [...byFeedbackId.values()].sort((a, b) => a.createdAt - b.createdAt);\n}\n\nexport class KeatingStorage {\n\tprivate db: IDBDatabase | null = null;\n\tprivate dbPromise: Promise<IDBDatabase> | null = null;\n\tprivate learnerStateWriteQueue: Promise<void> = Promise.resolve();\n\tcurrentSessionId: string | null = null;\n\n\tsetCurrentSessionId(id: string | null): void {\n\t\tthis.currentSessionId = id;\n\t}\n\n\tasync init(): Promise<void> {\n\t\tif (this.db) return;\n\t\tif (this.dbPromise) {\n\t\t\tawait this.dbPromise;\n\t\t\treturn;\n\t\t}\n\n\t\tthis.dbPromise = new Promise((resolve, reject) => {\n\t\t\tconst request = indexedDB.open(DB_NAME, DB_VERSION);\n\n\t\t\trequest.onerror = () => {\n\t\t\t\tthis.dbPromise = null;\n\t\t\t\treject(request.error);\n\t\t\t};\n\t\t\trequest.onblocked = () => {\n\t\t\t\tconsole.warn(\"Keating storage upgrade is waiting for another tab to close its old database connection.\");\n\t\t\t};\n\n\t\t\trequest.onsuccess = () => {\n\t\t\t\tthis.db = request.result;\n\t\t\t\tthis.db.onversionchange = () => {\n\t\t\t\t\tthis.db?.close();\n\t\t\t\t\tthis.db = null;\n\t\t\t\t\tthis.dbPromise = null;\n\t\t\t\t};\n\t\t\t\tresolve(this.db);\n\t\t\t};\n\n\t\t\trequest.onupgradeneeded = (event) => {\n\t\t\t\tconst db = (event.target as IDBOpenDBRequest).result;\n\n\t\t\t\t// Create object stores\n\t\t\t\tObject.values(STORES).forEach(