           slug: deck.slug,\n            title: deck.title,\n            description: deck.description,\n            cards: deck.cards,\n            createdAt: deck.createdAt ?? now,\n            updatedAt: now,\n            sessionId: deck.sessionId ?? this.currentSessionId ?? undefined,\n        };\n        await this.put(STORES.DECKS, record);\n        return record;\n    }\n    async getDecks(topic) {\n        if (topic) {\n            return this.getByTopic(STORES.DECKS, topic);\n        }\n        return this.getAll(STORES.DECKS);\n    }\n    async getDeck(id) {\n        const decks = await this.getDecks();\n        return decks.find((d) => d.id === id) ?? null;\n    }\n    async getDeckBySlug(slug) {\n        const decks = await this.getDecks();\n        return decks.find((d) => d.slug === slug) ?? null;\n    }\n    async updateDeckCardSrs(deckId, cardId, srs, updatedAt = Date.now()) {\n        const deck = await this.getDeck(deckId);\n        if (!deck)\n            return null;\n        let changed = false;\n        const cards = deck.cards.map((card) => {\n            if (card.id !== cardId)\n                return card;\n            changed = true;\n            return { ...card, srs, updatedAt };\n        });\n        if (!changed)\n            return deck;\n        const updated = { ...deck, cards, updatedAt };\n        await this.put(STORES.DECKS, updated);\n        return updated;\n    }\n    async deleteDeck(id) {\n        await this.deleteById(STORES.DECKS, id);\n    }\n    async recordCardReview(review) {\n        const record = {\n            id: review.id ?? this.generateId(),\n            deckId: review.deckId,\n            cardId: review.cardId,\n            topic: review.topic,\n            slug: review.slug,\n            rating: review.rating,\n            appliedIntervalDays: review.appliedIntervalDays,\n            easeAfter: review.easeAfter,\n            previousIntervalDays: review.previousIntervalDays,\n            isLapse: review.isLaps